    P_max, ix, cn0 = z_score(P)
    
    coffs = np.arange(N, dtype='float32') / fs
    dop = sdr_func.fine_dop(P.T[ix[1]], fds, ix[0])
    
    # print("PMAX:", P_max)
    # return P / P_max, fds, coffs, ix, cn0, dop, P_max
    return P, fds, coffs, ix, cn0, dop, P_max

